SELECT teacher, role, creator FROM (SELECT owner AS teacher, 'owner' AS role, 1 AS creator FROM subject_info WHERE id = CAST(:subject_id AS INTEGER) AND owner <> '' UNION ALL SELECT teacher AS teacher, role AS role, 0 AS creator FROM subject_teacher WHERE subject_id = CAST(:subject_id AS INTEGER) AND teacher NOT IN (SELECT owner FROM subject_info WHERE id = CAST(:subject_id AS INTEGER))) ORDER BY creator DESC, CASE role WHEN 'owner' THEN 0 ELSE 1 END, teacher
